create table public.family_links(user_id uuid references auth.users(id) on delete cascade,player_id uuid references public.team_players(id) on delete cascade,relationship text not null check(relationship in ('parent','player')),primary key(user_id,player_id));
alter table public.family_links enable row level security;
create index on public.family_links(player_id);
create function team_private.linked(p uuid,parent_only boolean default false) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.family_links l join public.team_memberships m on m.user_id=l.user_id and m.role=l.relationship where l.user_id=auth.uid() and l.player_id=p and (not parent_only or l.relationship='parent'))$$;
revoke all on function team_private.linked(uuid,boolean) from public;
grant execute on function team_private.linked(uuid,boolean) to authenticated;
revoke all on public.family_links from anon,authenticated;
grant select,insert,update,delete on public.family_links to authenticated;
create policy link_read on public.family_links for select to authenticated using(user_id=(select auth.uid()) or (select team_private.has_role('administrator')));
create policy link_admin on public.family_links for all to authenticated using((select team_private.has_role('administrator'))) with check((select team_private.has_role('administrator')));
create policy family_roster_update on public.team_players for update to authenticated using(team_private.linked(id)) with check(team_private.linked(id));
create table public.team_events(id uuid primary key default gen_random_uuid(),title text not null check(length(title) between 1 and 120),type text not null check(type in ('Practice','Tournament')),date date not null,time time not null,location text not null default '',cancelled boolean not null default false);
alter table public.team_events enable row level security;
create table public.team_documents(key text primary key check(key in ('finances','dues','announcements')),data jsonb not null check(jsonb_typeof(data)='object'),version integer not null default 1,updated_at timestamptz not null default now());
alter table public.team_documents enable row level security;
insert into public.team_documents(key,data) values
('finances','{"transactions":[],"budgets":{"Tournaments":{"budget":0,"reserved":0},"Gym rental":{"budget":0,"reserved":0},"Uniforms":{"budget":0,"reserved":0},"Equipment":{"budget":0,"reserved":0},"Other":{"budget":0,"reserved":0}},"history":[],"reconciled":null}'),
('dues','{"monthly":0,"months":1,"support":{},"history":[]}'),
('announcements','{"items":[]}');
create table public.team_availability(event_id uuid references public.team_events(id) on delete cascade,player_id uuid references public.team_players(id) on delete cascade,response text not null check(response in ('Available','Unavailable','Unsure')),updated_by uuid not null default auth.uid() references auth.users(id),primary key(event_id,player_id));
create index on public.team_availability(player_id);
alter table public.team_availability enable row level security;
create table public.parent_consents(id uuid primary key default gen_random_uuid(),player_id uuid not null references public.team_players(id),parent_id uuid not null default auth.uid() references auth.users(id),version text not null,payload jsonb not null check(jsonb_typeof(payload)='object'),recorded_at timestamptz not null default now());
create index on public.parent_consents(player_id);
create index on public.parent_consents(parent_id);
alter table public.parent_consents enable row level security;
create table public.team_change_history(id bigint generated always as identity primary key,actor uuid,resource text not null,action text not null,recorded_at timestamptz not null default now());
alter table public.team_change_history enable row level security;
create function team_private.record_change() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.team_change_history(actor,resource,action) values(auth.uid(),tg_table_name,tg_op); return null; end$$;
revoke all on function team_private.record_change() from public;
create trigger documents_history after update on public.team_documents for each row execute function team_private.record_change();
create trigger events_history after insert or update or delete on public.team_events for each row execute function team_private.record_change();
revoke all on public.team_events,public.team_documents,public.team_availability,public.parent_consents,public.team_change_history from anon,authenticated;
grant select,insert,update,delete on public.team_events,public.team_documents,public.team_availability to authenticated;
grant select,insert on public.parent_consents to authenticated;
grant select on public.team_change_history to authenticated;
create policy events_read on public.team_events for select to authenticated using(exists(select 1 from public.team_memberships where user_id=(select auth.uid())));
create policy events_staff on public.team_events for all to authenticated using((select team_private.has_role('administrator')) or (select team_private.has_role('coach'))) with check((select team_private.has_role('administrator')) or (select team_private.has_role('coach')));
create policy document_read on public.team_documents for select to authenticated using((select team_private.has_role('administrator')) or (key='announcements' and exists(select 1 from public.team_memberships where user_id=(select auth.uid()))));
create policy document_update on public.team_documents for update to authenticated using((select team_private.has_role('administrator')) or (key='announcements' and (select team_private.has_role('coach')))) with check((select team_private.has_role('administrator')) or (key='announcements' and (select team_private.has_role('coach'))));
create policy availability_read on public.team_availability for select to authenticated using(team_private.linked(player_id) or (select team_private.has_role('administrator')) or (select team_private.has_role('coach')));
create policy availability_write on public.team_availability for all to authenticated using(team_private.linked(player_id) or (select team_private.has_role('administrator'))) with check((team_private.linked(player_id) or (select team_private.has_role('administrator'))) and updated_by=(select auth.uid()));
create policy consent_read on public.parent_consents for select to authenticated using(team_private.linked(player_id,true) or (select team_private.has_role('administrator')));
create policy consent_insert on public.parent_consents for insert to authenticated with check(parent_id=(select auth.uid()) and team_private.linked(player_id,true));
create policy change_history_read on public.team_change_history for select to authenticated using((select team_private.has_role('administrator')));
create function team_private.player_dues(p uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare d jsonb; s jsonb; begin
if auth.uid() is null or not (team_private.linked(p) or team_private.has_role('administrator')) then raise exception 'Not authorized' using errcode='42501'; end if;
select data into d from public.team_documents where key='dues';
s=d->'support'->p::text;
return jsonb_build_object('monthly',d->'monthly','months',d->'months','support',jsonb_build_object(p::text,jsonb_build_object('full',coalesce((s->>'full')::boolean,false),'amount',coalesce((s->>'amount')::numeric,0))));
end$$;
revoke all on function team_private.player_dues(uuid) from public;
grant execute on function team_private.player_dues(uuid) to authenticated;
create function public.get_player_dues(p uuid) returns jsonb language sql security invoker set search_path='' as $$select team_private.player_dues(p)$$;
revoke all on function public.get_player_dues(uuid) from public,anon;
grant execute on function public.get_player_dues(uuid) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('team-photos','team-photos',false,5242880,array['image/jpeg','image/png','image/webp']);
create function team_private.photo_access(path text,writing boolean) returns boolean language plpgsql stable security definer set search_path='' as $$declare identifier uuid; begin
if auth.uid() is null then return false; end if;
if team_private.has_role('administrator') then return true; end if;
begin identifier:=split_part(path,'/',2)::uuid; exception when invalid_text_representation then return false; end;
if split_part(path,'/',1)='accounts' then return identifier=auth.uid(); end if;
if split_part(path,'/',1)='players' then return team_private.linked(identifier) or team_private.has_role('coach'); end if;
return false;end$$;
revoke all on function team_private.photo_access(text,boolean) from public;
grant execute on function team_private.photo_access(text,boolean) to authenticated;
create policy photo_read on storage.objects for select to authenticated using(bucket_id='team-photos' and team_private.photo_access(name,false));
create policy photo_insert on storage.objects for insert to authenticated with check(bucket_id='team-photos' and team_private.photo_access(name,true));
create policy photo_update on storage.objects for update to authenticated using(bucket_id='team-photos' and team_private.photo_access(name,true)) with check(bucket_id='team-photos' and team_private.photo_access(name,true));
create policy photo_delete on storage.objects for delete to authenticated using(bucket_id='team-photos' and team_private.photo_access(name,true));
